@dataclass
class PcaCounts:
    """0x8B PCA_COUNTS (event). 16 PCA9685 OFF counts (bit 12 = full-off)."""
    ID: ClassVar[int] = 0x8B
    NAME: ClassVar[str] = 'PCA_COUNTS'
    KIND: ClassVar[Kind] = Kind.EVENT
    DIR: ClassVar[Dir] = Dir.BODY_TO_PI
    HAS_EPOCH: ClassVar[bool] = False
    IS_QUERY: ClassVar[bool] = False
    REPLY_TO: ClassVar[int | None] = 0x06
    MIN_LEN: ClassVar[int] = 32
    MAX_LEN: ClassVar[int] = 32
    _FMT: ClassVar[struct.Struct] = struct.Struct('<HHHHHHHHHHHHHHHH')
    counts: list[int] = field(default_factory=lambda: [0] * 16)  # count

    def _fixed_values(self) -> list:
        v: list = []
        if len(self.counts) != 16:
            raise PayloadError('counts: expected 16 elements')
        v.extend(self.counts)
        return v

    @classmethod
    def _from_fixed(cls, v: tuple, **extra):
        kw: dict = {}
        kw['counts'] = list(v[0:16])
        kw.update(extra)
        return cls(**kw)

    def pack(self) -> bytes:
        try:
            return self._FMT.pack(*self._fixed_values())
        except struct.error as e:
            raise PayloadError(f'{type(self).__name__}: {e}') from None

    @classmethod
    def unpack(cls, data: bytes):
        if len(data) != cls._FMT.size:
            raise PayloadError(f'{cls.__name__}: length {len(data)} != {cls._FMT.size}')
        return cls._from_fixed(cls._FMT.unpack(bytes(data)))


@dataclass
class Log:
    """0x8F LOG (stream). Debug builds only. ASCII text, 1..60 B, no terminator."""
    ID: ClassVar[int] = 0x8F
    NAME: ClassVar[str] = 'LOG'
    KIND: ClassVar[Kind] = Kind.STREAM
    DIR: ClassVar[Dir] = Dir.BODY_TO_PI
    HAS_EPOCH: ClassVar[bool] = False
    IS_QUERY: ClassVar[bool] = False
    REPLY_TO: ClassVar[int | None] = None
    MIN_LEN: ClassVar[int] = 1
    MAX_LEN: ClassVar[int] = 60
    _FMT: ClassVar[struct.Struct] = struct.Struct('<')
    text: bytes = b''  # 1..60 B

    def _fixed_values(self) -> list:
        v: list = []
        return v

    @classmethod
    def _from_fixed(cls, v: tuple, **extra):
        kw: dict = {}
        kw.update(extra)
        return cls(**kw)

    def pack(self) -> bytes:
        tail = bytes(self.text)
        n = len(tail)
        if not 1 <= n <= 60:
            raise PayloadError('text: 1..60 elements, got %d' % n)
        try:
            return self._FMT.pack(*self._fixed_values()) + tail
        except struct.error as e:
            raise PayloadError(f'{type(self).__name__}: {e}') from None

    @classmethod
    def unpack(cls, data: bytes):
        data = bytes(data)
        if payload_len_status(cls.ID, data) != LEN_OK:
            raise PayloadError(f'{cls.__name__}: bad length {len(data)}')
        v = cls._FMT.unpack(data[:0])
        rest = data[0:]
        return cls._from_fixed(v, text=rest)


