def payload_len_status(msg_type: int, payload: bytes) -> int:
    """LEN_OK, LEN_BAD or LEN_UNKNOWN_TYPE, exactly as kilo_payload_len_check() in C."""
    n = len(payload)
    if msg_type == 0x01:
        return LEN_OK if n == 0 else LEN_BAD
    if msg_type == 0x02:
        return LEN_OK if n == 0 else LEN_BAD
    if msg_type == 0x03:
        return LEN_OK if n == 2 else LEN_BAD
    if msg_type == 0x04:
        return LEN_OK if n == 3 else LEN_BAD
    if msg_type == 0x05:
        return LEN_OK if n == 0 else LEN_BAD
    if msg_type == 0x06:
        return LEN_OK if n == 0 else LEN_BAD
    if msg_type == 0x10:
        return LEN_OK if n == 4 else LEN_BAD
    if msg_type == 0x11:
        return LEN_OK if n == 11 else LEN_BAD
    if msg_type == 0x12:
        return LEN_OK if n == 10 else LEN_BAD
    if msg_type == 0x13:
        return LEN_OK if n == 7 else LEN_BAD
    if msg_type == 0x14:
        return LEN_OK if n == 5 else LEN_BAD
    if msg_type == 0x20:
        return LEN_OK if n == 11 else LEN_BAD
    if msg_type == 0x21:
        if not 16 <= n <= 58:
            return LEN_BAD
        return LEN_OK if n == 2 + 14 * payload[1] else LEN_BAD
    if msg_type == 0x22:
        return LEN_OK if n == 3 else LEN_BAD
    if msg_type == 0x23:
        return LEN_OK if n == 4 else LEN_BAD
    if msg_type == 0x24:
        return LEN_OK if n == 1 else LEN_BAD
    if msg_type == 0x30:
        return LEN_OK if n == 4 else LEN_BAD
    if msg_type == 0x31:
        if not 3 <= n <= 17:
            return LEN_BAD
        return LEN_OK if n == 1 + 2 * payload[0] else LEN_BAD
    if msg_type == 0x38:
        return LEN_OK if n == 0 else LEN_BAD
    if msg_type == 0x39:
        return LEN_OK if n == 3 else LEN_BAD
    if msg_type == 0x3A:
        return LEN_OK if n == 0 else LEN_BAD
    if msg_type == 0x3B:
        return LEN_OK if n == 0 else LEN_BAD
    if msg_type == 0x3C:
        return LEN_OK if n == 13 else LEN_BAD
    if msg_type == 0x3D:
        return LEN_OK if n == 1 else LEN_BAD
    if msg_type == 0x3E:
        return LEN_OK if n == 4 else LEN_BAD
    if msg_type == 0x3F:
        return LEN_OK if n == 3 else LEN_BAD
    if msg_type == 0x7E:
        return LEN_OK if n == 2 else LEN_BAD
    if msg_type == 0x80:
        return LEN_OK if n == 16 else LEN_BAD
    if msg_type == 0x81:
        return LEN_OK if n == 26 else LEN_BAD
    if msg_type == 0x82:
        return LEN_OK if n == 24 else LEN_BAD
    if msg_type == 0x83:
        return LEN_OK if n == 14 else LEN_BAD
    if msg_type == 0x84:
        return LEN_OK if n == 3 else LEN_BAD
    if msg_type == 0x85:
        return LEN_OK if n == 6 else LEN_BAD
    if msg_type == 0x86:
        return LEN_OK if n == 32 else LEN_BAD
    if msg_type == 0x87:
        return LEN_OK if n == 9 else LEN_BAD
    if msg_type == 0x88:
        return LEN_OK if 3 <= n <= 58 else LEN_BAD
    if msg_type == 0x89:
        return LEN_OK if n == 4 else LEN_BAD
    if msg_type == 0x8A:
        return LEN_OK if n == 19 else LEN_BAD
    if msg_type == 0x8B:
        return LEN_OK if n == 32 else LEN_BAD
    if msg_type == 0x8F:
        return LEN_OK if 1 <= n <= 60 else LEN_BAD
    return LEN_UNKNOWN_TYPE


def decode_payload(msg_type: int, payload: bytes) -> Any:
    """Unpack a payload into its dataclass. Raises KeyError (unknown type) or PayloadError."""
    return MESSAGES[msg_type].unpack(payload)


def to_dict(obj: Any) -> Any:
    """Message/struct -> plain JSON-able dict (bytes as hex strings)."""
    if isinstance(obj, (bytes, bytearray)):
        return bytes(obj).hex()
    if isinstance(obj, list):
        return [to_dict(x) for x in obj]
    if hasattr(obj, '__dataclass_fields__'):
        return {f.name: to_dict(getattr(obj, f.name)) for f in dc_fields(obj)}
    return obj


def from_dict(cls: type, d: dict) -> Any:
    """Inverse of to_dict for a message or struct class."""
    kw = {}
    for f in dc_fields(cls):
        k = f.name
        if k not in d:
            continue
        v = d[k]
        t = str(f.type)
        if t == 'bytes':
            v = bytes.fromhex(v)
        elif t.startswith('list[') and t != 'list[int]':
            ec = globals()[t[5:-1]]
            v = [from_dict(ec, x) for x in v]
        kw[k] = v
    return cls(**kw)
